7	/// Helper trait to encode instructions into a "sink".
8	pub trait Encode {
9	    /// The encoded width of this instruction.
10	    const WIDTH: u8;
11	
12	    /// Encodes this operand or instruction into the provided `sink`.
13	    fn encode<E>(&self, sink: &mut E)
14	    where
15	        E: Extend<u8>;
16	}
